const calibrationSteps=['Headset check','Signal quality','Resting baseline','Focus activity','Complete']
export function StudentCalibration() {
  const navigate=useNavigate(); const [step,setStep]=useState(0); const pct=[10,28,52,78,100][step]
  // @ts-expect-error Compact prototype sequence retains its future dynamic index.
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  return <CalmZoneTemplate showNav={false}><div className={styles.pageNarrow}><button className={styles.ghost} onClick={()=>navigate('/student/eeg-pairing')}><ArrowLeft size={14}/> Exit calibration</button><div className={styles.stepper}>{calibrationSteps.map((s,i)=><div key={s} className={`${styles.step} ${i===step?styles.stepActive:i<step?styles.stepDone:''}`}><span className={styles.stepDot}>{i<step?<Check size={12}/>:i+1}</span><span>{s}</span></div>)}</div><div className={styles.card}><div className={styles.center}><div className={styles.heroIcon}>{step===0?<Headphones size={32}/>:step<3?<Waves size={32}/>:step===3?<Brain size={32}/>:<Check size={32}/>}</div><span className={styles.eyebrow}>Step {step+1} of 5</span><h1 className={styles.title}>{['Fit your EEG headband','Checking signal quality','Stay still and relax','Focus on the activity','Calibration complete'][step]}</h1><p className={styles.subtitle} style={{margin:'8px auto 20px'}}>{['Place the sensors firmly against your forehead and behind each ear.','All four channels should remain stable before continuing.','Look at the center dot and breathe normally while Cortex learns your resting pattern.','Follow the simple shape sequence while Cortex learns your attentive pattern.','Your personal baseline is ready for this learning session.'][step]}</p></div>{step===1&&<div className={styles.grid4}>{['TP9','AF7','AF8','TP10'].map((x,i)=><div className={styles.card} key={x} style={{padding:12,textAlign:'center'}}><span className={i===2?styles.badgeGold:styles.badge}>{i===2?'Fair':'Good'}</span><strong style={{display:'block',marginTop:7,fontSize:12}}>{x}</strong></div>)}</div>}{step===2&&<div className={styles.center}><div style={{fontSize:56,color:'var(--color-interface-purple)'}}>●</div><span className={styles.muted}>00:{String(30-step*3).padStart(2,'0')} remaining</span></div>}{step===3&&<div className={styles.grid3}>{['● ▲ ■','▲ ■ ●','■ ● ▲'].map((x,i)=><button className={styles.secondary} key={x} style={{height:58,fontSize:18}}>{x}</button>)}</div>}<div className={styles.progress} style={{marginTop:22}}><div className={styles.progressFill} style={{width:`${pct}%`}}/></div><div className={styles.actions} style={{justifyContent:'space-between',marginTop:16}}><button className={styles.secondary} disabled={step===0} onClick={()=>setStep(Math.max(0,step-1))}>Back</button><button className={styles.primary} onClick={()=>step===4?navigate('/student/mode-select'):setStep(step+1)}>{step===4?'Choose learning mode':'Continue'} <ChevronRight size={13}/></button></div></div></div></CalmZoneTemplate>
}

const wavePaths=['M0 50 C20 5 35 95 55 50 S90 5 110 50 S145 95 165 50 S200 5 220 50 S255 95 275 50 S310 5 330 50 S365 95 385 50 S420 5 440 50 S475 95 500 50','M0 50 C15 25 30 75 45 50 S75 25 90 50 S120 75 135 50 S165 25 180 50 S210 75 225 50 S255 25 270 50 S300 75 315 50 S345 25 360 50 S390 75 405 50 S435 25 450 50 S480 75 500 50']
