export function Evaluation() {
 const [tab,setTab]=useState('checklist'); const criteria=[['Authentication & RBAC','Passed','All three roles have defined access templates'],['EEG acquisition','Review','Hardware bridge pending integration'],['Adaptive content rules','Passed','Four state mappings verified'],['Teacher override','Passed','Focus and Relax controls available'],['Journal workflow','Passed','Text, drawing, and audio templates available'],['Closed-loop latency','Review','Requires physical EEG testing']]
 return <AdminShell active="evaluation"><div className={styles.page}><div className={styles.header}><div><span className={styles.eyebrow}>System validation</span><h1 className={styles.title}>Evaluation workspace</h1><p className={styles.subtitle}>Document functional checks, adaptation reviews, test evidence, and stakeholder acceptance.</p></div><button className={styles.primary}><Plus size={13}/> New evaluation run</button></div><div className={styles.grid4}>{[['82%','Functional completeness'],['4.3/5','Appropriateness'],['88%','User acceptance'],['6','Open findings']].map(([v,l],i)=><div className={styles.card} key={l}><div className={styles.stat}><div className={styles.score} style={{'--score':`${[82,86,88,64][i]}%`} as React.CSSProperties}><span>{[82,86,88,64][i]}</span></div><span><span className={styles.listName}>{v}</span><span className={styles.listMeta}>{l}</span></span></div></div>)}</div><div className={`${styles.tabs} ${styles.section}`}><button className={`${styles.tab} ${tab==='checklist'?styles.tabActive:''}`} onClick={()=>setTab('checklist')}>Functional checklist</button><button className={`${styles.tab} ${tab==='adaptation'?styles.tabActive:''}`} onClick={()=>setTab('adaptation')}>Adaptation review</button><button className={`${styles.tab} ${tab==='uat'?styles.tabActive:''}`} onClick={()=>setTab('uat')}>User acceptance</button></div>{tab==='checklist'?<div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>Criterion</th><th>Result</th><th>Evidence / notes</th><th>Reviewer</th></tr></thead><tbody>{criteria.map(c=><tr key={c[0]}><td><strong>{c[0]}</strong></td><td><span className={c[1]==='Passed'?styles.badge:styles.badgeGold}>{c[1]}</span></td><td>{c[2]}</td><td>Internal QA</td></tr>)}</tbody></table></div>:tab==='adaptation'?<div className={styles.grid2}>{['Focused → Focus content','Distracted → Elevated prompts','Relaxed → Calm content','Overstimulated → Reduced intensity'].map((x,i)=><div className={styles.card} key={x}><div className={styles.sectionHead}><h3 className={styles.cardTitle}>{x}</h3><span className={styles.badge}>{[4.6,4.2,4.5,4.0][i]}/5</span></div><label className={styles.field}><span className={styles.label}>Reviewer notes</span><textarea className={styles.textarea} defaultValue="Appropriate for the detected cognitive state and curriculum activity."/></label><div className={styles.actions} style={{marginTop:10}}><button className={styles.secondary}>Mark mismatch</button><button className={styles.primary}>Approve</button></div></div>)}</div>:<div className={styles.card}><h2 className={styles.cardTitle}>User acceptance summary</h2><p className={styles.cardSub}>Prototype values for teacher and student evaluation instruments.</p><div className={styles.divider}/><div className={styles.list}>{[['Functional suitability',91],['Usability',88],['Reliability',82],['Performance efficiency',86],['Overall satisfaction',90]].map(([n,v])=><div className={styles.listItem} key={n}><span className={styles.listName}>{n}</span><div className={styles.progress} style={{width:'55%'}}><div className={styles.progressFill} style={{width:`${v}%`}}/></div><strong>{v}%</strong></div>)}</div></div>}</div></AdminShell>
}

export function DrawingJournal() {
 const navigate=useNavigate(); const canvas=useRef<HTMLCanvasElement>(null); const drawing=useRef(false); const [color,setColor]=useState('#534ab7')
 useEffect(()=>{const c=canvas.current;if(!c)return;const rect=c.getBoundingClientRect();c.width=rect.width*devicePixelRatio;c.height=340*devicePixelRatio;const ctx=c.getContext('2d');ctx?.scale(devicePixelRatio,devicePixelRatio);if(ctx){ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=5}},[])
 const point=(e:React.PointerEvent<HTMLCanvasElement>)=>{const r=e.currentTarget.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top]}
 const start=(e:React.PointerEvent<HTMLCanvasElement>)=>{drawing.current=true;const ctx=canvas.current?.getContext('2d');const [x,y]=point(e);ctx?.beginPath();ctx?.moveTo(x,y)}
 const move=(e:React.PointerEvent<HTMLCanvasElement>)=>{if(!drawing.current)return;const ctx=canvas.current?.getContext('2d');const [x,y]=point(e);if(ctx){ctx.strokeStyle=color;ctx.lineTo(x,y);ctx.stroke()}}
 return <PlayfulZoneTemplate showNav={false}><div className={styles.pageNarrow}><div className={styles.header}><div><span className={styles.eyebrow}>Learning journal</span><h1 className={styles.title}>Draw what you learned</h1><p className={styles.subtitle}>Show your favorite part of today’s activity.</p></div><button className={styles.ghost} onClick={()=>navigate('/student/journal')}>Close</button></div><div className={styles.card}><div className={styles.toolbar}>{['#534ab7','#1d9e75','#d4537e','#ef9f27','#1a1a2e'].map(c=><button key={c} aria-label={`Use ${c}`} className={`${styles.color} ${color===c?styles.colorActive:''}`} style={{background:c}} onClick={()=>setColor(c)}/>)}<button className={styles.secondary} onClick={()=>{const c=canvas.current;c?.getContext('2d')?.clearRect(0,0,c.width,c.height)}}><Trash2 size={13}/> Clear</button></div><canvas ref={canvas} className={styles.canvas} onPointerDown={start} onPointerMove={move} onPointerUp={()=>drawing.current=false} onPointerLeave={()=>drawing.current=false}/><div className={styles.actions} style={{justifyContent:'flex-end',marginTop:14}}><button className={styles.secondary} onClick={()=>navigate('/student/journal')}>Cancel</button><button className={styles.primary} onClick={()=>navigate('/student/home')}><Save size={13}/> Save drawing</button></div></div></div></PlayfulZoneTemplate>
}

export function AudioJournal() {
 const navigate=useNavigate(); const [recording,setRecording]=useState(false); const [seconds,setSeconds]=useState(0); const [ready,setReady]=useState(false)
 useEffect(()=>{if(!recording)return;const id=setInterval(()=>setSeconds(s=>s+1),1000);return()=>clearInterval(id)},[recording])
 const toggle=()=>{if(recording){setRecording(false);setReady(true)}else{setSeconds(0);setReady(false);setRecording(true)}}
 return <PlayfulZoneTemplate showNav={false}><div className={styles.pageNarrow}><div className={styles.card}><div className={styles.center}><span className={styles.eyebrow}>Learning journal</span><h1 className={styles.title}>Tell me about your session</h1><p className={styles.subtitle} style={{margin:'8px auto'}}>Record a short reflection about what you learned and how you felt.</p><button className={`${styles.recordButton} ${recording?styles.recording:''}`} onClick={toggle} aria-label={recording?'Stop recording':'Start recording'}>{recording?<Square size={24}/>:<Mic size={28}/>}</button><strong style={{fontSize:20,color:'var(--color-deep-purple)'}}>{String(Math.floor(seconds/60)).padStart(2,'0')}:{String(seconds%60).padStart(2,'0')}</strong><p className={styles.muted}>{recording?'Recording… tap to stop':ready?'Recording ready to review':'Tap the microphone to begin'}</p></div>{ready&&<div className={styles.wavePanel} style={{marginTop:18}}><div style={{display:'flex',alignItems:'center',gap:12}}><button className={styles.primary}><Play size={13}/></button><div className={styles.progress} style={{flex:1,background:'#4b497a'}}><div className={styles.progressFill} style={{width:'38%',background:'#82b9ff'}}/></div><span style={{fontSize:11}}>00:{String(seconds).padStart(2,'0')}</span></div></div>}<div className={styles.actions} style={{justifyContent:'center',marginTop:18}}><button className={styles.secondary} onClick={()=>navigate('/student/journal')}>Cancel</button><button className={styles.primary} disabled={!ready} onClick={()=>navigate('/student/home')}><Save size={13}/> Save recording</button></div></div></div></PlayfulZoneTemplate>
}
